<?php
declare(strict_types=1);
require_once __DIR__ . '/_layout.php';
require_once __DIR__ . '/../../../lib/content.php';

$csrf = csrf_token(); $editId = max(0, (int)($_GET['edit'] ?? 0)); $isNew = isset($_GET['new']); $news = []; $editing = null; $error = null;
try {
    if (!$isNew && $editId === 0) $news = db()->query('SELECT id, version, data, hidden, create_at FROM news ORDER BY create_at DESC, id DESC')->fetchAll();
    elseif ($editId > 0) { $stmt = db()->prepare('SELECT id, version, data, hidden, create_at FROM news WHERE id = :id'); $stmt->execute([':id' => $editId]); $editing = $stmt->fetch() ?: null; if (!$editing) $error = 'Новость не найдена. Возможно, её уже удалили.'; }
} catch (Throwable $e) { error_log('Admin news page error: ' . $e->getMessage()); $error = 'Не удалось загрузить новости. Проверьте подключение к базе данных.'; }
$formData = $editing ? news_data((string)$editing['data']) : ['blocks' => [], 'images' => []]; if (!$formData['blocks']) $formData['blocks'] = [['title' => '', 'description' => '', 'tooltip' => '']];
$formVersion = (string)($editing['version'] ?? ''); $formHidden = !empty($editing['hidden']); $showForm = $isNew || $editing !== null;
$formDate = $editing ? date('Y-m-d\\TH:i', strtotime((string)$editing['create_at'])) : date('Y-m-d\\TH:i');
function admin_news_date(?string $value): string { return $value ? date('d.m.Y H:i', strtotime($value)) : '—'; }
dash_start('news', 'Новости');
?>
<?php if (isset($_GET['saved'])): ?><p class="success-message notice" role="status">Новость сохранена.</p><?php endif; ?>
<?php if (isset($_GET['deleted'])): ?><p class="success-message notice" role="status">Новость удалена.</p><?php endif; ?>
<?php if (isset($_GET['toggled'])): ?><p class="success-message notice" role="status">Видимость новости изменена.</p><?php endif; ?>
<?php if (isset($_GET['error'])): ?><p class="form-error notice" role="alert"><?= ($_GET['error'] ?? '') === 'empty' ? 'Добавьте версию, текст или картинку.' : (($_GET['error'] ?? '') === 'date' ? 'Укажите корректные дату и время новости.' : 'Не удалось сохранить новость. Проверьте данные и попробуйте ещё раз.') ?></p><?php endif; ?>
<?php if ($error): ?><p class="form-error notice" role="alert"><?= e($error) ?></p><?php endif; ?>

<?php if (!$showForm): ?><section class="panel-card table-panel"><div class="table-heading"><div><h2>Новости</h2><p>Публикации на странице «Новости». Скрытые записи не видны посетителям.</p></div><a class="btn-secondary" href="/admin/dashboard/news?new=1">+ Новая новость</a></div>
<?php if (!$news): ?><p class="empty-state">Новостей пока нет. Добавьте первую публикацию.</p><?php else: ?><div class="table-scroll"><table class="users-table"><thead><tr><th>ID</th><th>Версия</th><th>Заголовок</th><th>Дата новости</th><th>Статус</th><th>Действия</th></tr></thead><tbody>
<?php foreach ($news as $item): $itemData = news_data((string)$item['data']); ?><tr><td><?= (int)$item['id'] ?></td><td><?= $item['version'] !== '' ? e((string)$item['version']) : '—' ?></td><td><?= e(news_first_title($itemData)) ?: '—' ?></td><td><?= e(admin_news_date($item['create_at'])) ?></td><td><span class="badge <?= $item['hidden'] ? 'badge-muted' : 'badge-success' ?>"><?= $item['hidden'] ? 'Скрыта' : 'Опубликована' ?></span></td><td class="actions-cell"><a class="btn-secondary" href="/admin/dashboard/news?edit=<?= (int)$item['id'] ?>">Изменить</a><form method="post" action="/api/toggle-news" class="inline-form"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button class="btn-secondary" type="submit"><?= $item['hidden'] ? 'Показать' : 'Скрыть' ?></button></form><form method="post" action="/api/delete-news" class="inline-form" data-confirm="Удалить эту новость? Действие необратимо."><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button class="btn-secondary btn-danger" type="submit">Удалить</button></form></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?></section><?php endif; ?>

<?php if ($showForm): ?><section class="panel-card" id="news-form"><h2><?= $editing ? 'Редактировать новость #' . (int)$editing['id'] : 'Новая новость' ?></h2><p>Заполните дату публикации, блоки текста и изображения.</p>
<form method="post" action="/api/save-news-with-date" class="admin-form" enctype="multipart/form-data" data-submit-lock>
<input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)($editing['id'] ?? 0) ?>"><input type="hidden" name="form_token" value="<?= e(bin2hex(random_bytes(24))) ?>">
<div class="form-grid"><div class="field"><label for="news-version">Версия</label><input id="news-version" name="version" value="<?= e($formVersion) ?>" placeholder="v1.0.0" maxlength="120"></div><div class="field"><label for="news-date">Дата и время новости</label><input id="news-date" type="datetime-local" name="create_at" value="<?= e($formDate) ?>" required></div><div class="field"><span class="field-label">Видимость</span><label class="checkbox-row"><input type="checkbox" name="hidden" value="1"<?= $formHidden ? ' checked' : '' ?>> Скрыть новость</label></div></div>
<div class="field"><span class="field-label">Блоки новости</span><div class="news-blocks" data-blocks>
<?php foreach ($formData['blocks'] as $block): ?><div class="news-block" data-block><div class="news-block-head"><span class="label">Блок</span><button type="button" class="btn-secondary btn-danger" data-remove-block>Удалить</button></div><div class="field"><label>Заголовок</label><input name="block_title[]" value="<?= e($block['title']) ?>" maxlength="255"></div><div class="field"><label>Описание</label><textarea name="block_description[]" rows="4"><?= e($block['description']) ?></textarea></div><div class="field"><label>Текст подсказки при наведении (необязательно)</label><input name="block_tooltip[]" value="<?= e($block['tooltip'] ?? '') ?>" maxlength="500" placeholder="Пояснение, которое увидят при наведении"></div></div><?php endforeach; ?>
</div><div><button type="button" class="btn-secondary" data-add-block>+ Добавить блок</button></div></div>
<?php if ($formData['images']): ?><div class="field"><span class="field-label">Текущие картинки</span><div class="image-grid"><?php foreach ($formData['images'] as $index => $image): ?><label class="image-item"><img src="<?= e($image) ?>" alt=""><span class="checkbox-row"><input type="checkbox" name="remove_image[]" value="<?= (int)$index ?>"> Удалить</span></label><?php endforeach; ?></div></div><?php endif; ?>
<div class="field"><label>Новые картинки</label><label class="drop-zone compact-drop" data-drop-zone for="news-images"><span class="drop-icon" aria-hidden="true">↑</span><strong data-drop-title>Перетащите изображения сюда</strong><span>или нажмите, чтобы выбрать · до 3 файлов по 1 МБ</span><span class="upload-progress" data-upload-progress hidden><i></i></span></label><input id="news-images" class="visually-hidden-file" type="file" name="images[]" accept="image/png,image/jpeg,image/gif,image/webp,image/avif" multiple data-image-input><div class="selected-image-grid" data-selected-images></div></div>
<div class="field"><label for="news-image-urls">Или ссылки на картинки</label><textarea id="news-image-urls" name="image_urls" rows="3" placeholder="https://example.com/image.png"></textarea><span class="hint">По одной ссылке в строке.</span></div>
<div class="admin-actions"><button type="submit" class="btn">Сохранить</button><a class="btn-secondary" href="/admin/dashboard/news">Отмена</a></div></form></section>
<template id="news-block-template"><div class="news-block" data-block><div class="news-block-head"><span class="label">Блок</span><button type="button" class="btn-secondary btn-danger" data-remove-block>Удалить</button></div><div class="field"><label>Заголовок</label><input name="block_title[]" maxlength="255"></div><div class="field"><label>Описание</label><textarea name="block_description[]" rows="4"></textarea></div><div class="field"><label>Текст подсказки при наведении (необязательно)</label><input name="block_tooltip[]" maxlength="500" placeholder="Пояснение, которое увидят при наведении"></div></div></template>
<?php endif; ?>
<?php dash_end(); ?>
